
module EquivRep (equivRep) where

import Control.Monad.Union as Union

import Data.Map qualified as Map
import Control.Monad
import Data.List

-- given elements and a relation, leave only one element from each equivalence class generated by the relation.
-- precondition: elts has no duplicate elements and is closed under rel
equivRep
  rel
  elts
  = run $ do
  kvs <- traverse new' elts
  let kvMap = Map.fromList kvs
  forM_ kvs $ \(e1, n1) -> do
    forM_ (rel e1) $ \e2 -> do
      case Map.lookup e2 kvMap of
        Just n2 -> merge selectRep n1 n2 *> pure ()
        Nothing -> pure ()
  let findRep node = snd <$> (Union.lookup node)
  reps <- traverse findRep (fmap snd kvs)
  pure $ nub $ sort reps

new' k = do
  v <- Union.new k
  pure (k, v)

selectRep a b = (min a b, ())
